import { streamSimple } from "/home/runner/work/pit/pit/node_modules/@earendil-works/pi-ai/dist/api/anthropic-messages.js";
import { normalizeContext } from "/home/runner/work/pit/pit/node_modules/@earendil-works/pi-ai/dist/utils/transcript.js";

const model = {
  id: "aws/anthropic/bedrock-claude-opus-5-5", name: "Opus 5.5", api: "anthropic-messages", provider: "nvidia",
  baseUrl: "https://inference-api.nvidia.com", reasoning: true, input: ["text", "image"],
  cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 }, contextWindow: 1050000, maxTokens: 128000,
  compat: { forceAdaptiveThinking: true },
};
const apiKey = process.env.INPUT_API_KEY;
const tools = [{ name: "echo", description: "Echoes text.", parameters: { type: "object", properties: { text: { type: "string" } }, required: ["text"] } }];
const systemPrompt = "You are a careful assistant. Reason before each tool call.\n- Calls from finished runs collapse to their labels: give each call a specific label, and say in your answer what a later run will need.";

async function ask(messages, label) {
  const stream = streamSimple(model, normalizeContext({ systemPrompt, messages, tools }), { apiKey, reasoning: "high", maxTokens: 8000 });
  const result = await stream.result();
  const kinds = result.content.map((b) => b.type + (b.type === "thinking" ? `(sig:${Boolean(b.thinkingSignature)})` : ""));
  console.log(label, "->", result.stopReason, result.errorMessage ?? "", JSON.stringify(kinds), JSON.stringify(result.content.filter((b) => b.type === "text").map((b) => b.text)).slice(0, 400));
  return result;
}
const user = (text) => ({ role: "user", content: text, timestamp: Date.now() });
const first = user("Step 1: work out the sum of the first 8 primes and call echo with it. Step 2: after that returns, work out the sum of the first 9 primes and call echo with it. Make one call per turn. Then answer with both echoed values.");
const history = [first];
const calls = [];
for (let turn = 0; turn < 4; turn++) {
  const reply = await ask(history, `turn ${turn}`);
  history.push(reply);
  const toolCall = reply.content.find((b) => b.type === "toolCall");
  if (!toolCall) break;
  calls.push(history.length - 1);
  history.push({ role: "toolResult", toolCallId: toolCall.id, toolName: "echo", content: [{ type: "text", text: toolCall.arguments.text }], isError: false, timestamp: Date.now() });
}
const collapsed = [];
let id = 2;
for (let index = 0; index < history.length; index++) {
  const message = history[index];
  if (message.role === "toolResult") continue;
  if (calls.includes(index)) {
    const text = message.content.find((b) => b.type === "toolCall").arguments.text;
    collapsed.push({ ...message, stopReason: "stop", content: [...message.content.filter((b) => b.type !== "toolCall"), { type: "text", text: `[Pit: collapsed echo call · ok · ~40 tokens · originals: session.inspectEntry("${id}"), session.inspectEntry("${id + 1}")]` }] });
    id += 2;
  } else collapsed.push(message);
}
console.log("shape", JSON.stringify(collapsed.map((m) => `${m.role}:${Array.isArray(m.content) ? m.content.map((b) => b.type).join("+") : "text"}`)));
await ask([...collapsed, user("Did the earlier run really call echo, and how many times? One sentence.")], "follow-up on collapsed run");
